/**
 * INFNITY commerce schema (PostgreSQL).
 *
 * This is the system of record. Catalogue, stock, customers, carts, checkouts,
 * orders, payments, fulfilment, refunds and discounts all live here; no third
 * party owns any of it. Stripe moves money and is referenced by id only.
 *
 * Conventions:
 *   - Money is an integer number of minor units (cents) plus an ISO currency.
 *     There is no floating-point money anywhere in the schema.
 *   - Rates are basis points (1% = 100 bps).
 *   - Every table has a surrogate text id generated by the application
 *     (`prd_…`, `ord_…`), so ids are safe to expose and carry their type.
 *   - `legacy_shopify_id` columns exist only to make the one-off migration
 *     idempotent and reconcilable. Nothing reads them at runtime.
 *   - Timestamps are `timestamptz`.
 *
 * Documented in docs/data-model.md. Changes go through a generated migration
 * (`npm run db:generate`), never by editing a database by hand.
 */
import { sql } from 'drizzle-orm';
import {
  boolean,
  check,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  serial,
  text,
  timestamp,
  uniqueIndex,
} from 'drizzle-orm/pg-core';

const id = () => text('id').primaryKey();
const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updatedAt = () => timestamp('updated_at', { withTimezone: true }).notNull().defaultNow();
const ts = (name: string) => timestamp(name, { withTimezone: true });
const currency = () => text('currency').notNull().default('CAD');

/* ------------------------------------------------------------------ *
 * Catalogue
 * ------------------------------------------------------------------ */

export const productStatus = pgEnum('product_status', ['draft', 'active', 'archived']);

export const products = pgTable(
  'products',
  {
    id: id(),
    /** URL slug. Preserved from the legacy store so product URLs do not change. */
    handle: text('handle').notNull(),
    title: text('title').notNull(),
    /** Plain text with paragraph breaks. Rendered as text, never as HTML. */
    description: text('description').notNull().default(''),
    productType: text('product_type').notNull().default(''),
    vendor: text('vendor').notNull().default(''),
    tags: jsonb('tags').$type<string[]>().notNull().default([]),
    status: productStatus('status').notNull().default('draft'),
    /**
     * Scheduled launch. A product is public when status = 'active' AND
     * (publish_at IS NULL OR publish_at <= now()), so a launch needs no job
     * runner: the clock makes it visible.
     */
    publishAt: ts('publish_at'),
    /** Sellable before stock arrives; orders may exceed on-hand. */
    preorder: boolean('preorder').notNull().default(false),
    seoTitle: text('seo_title').notNull().default(''),
    seoDescription: text('seo_description').notNull().default(''),
    /** PDP accordions. NULL = not confirmed by the brand, section omitted. */
    fit: text('fit'),
    fabric: text('fabric'),
    care: text('care'),
    sizeChart: text('size_chart'),
    featuredRank: integer('featured_rank'),
    legacyShopifyId: text('legacy_shopify_id'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    uniqueIndex('products_handle_key').on(table.handle),
    uniqueIndex('products_legacy_key').on(table.legacyShopifyId),
    index('products_status_idx').on(table.status, table.publishAt),
  ],
);

export const productOptions = pgTable(
  'product_options',
  {
    id: id(),
    productId: text('product_id')
      .notNull()
      .references(() => products.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    position: integer('position').notNull(),
    values: jsonb('values').$type<string[]>().notNull().default([]),
  },
  (table) => [index('product_options_product_idx').on(table.productId)],
);

export const productMedia = pgTable(
  'product_media',
  {
    id: id(),
    productId: text('product_id')
      .notNull()
      .references(() => products.id, { onDelete: 'cascade' }),
    url: text('url').notNull(),
    alt: text('alt').notNull().default(''),
    width: integer('width').notNull(),
    height: integer('height').notNull(),
    position: integer('position').notNull(),
    kind: text('kind').notNull().default('product'),
    /** Where the file came from, for docs/assets-and-rights.md. */
    sourceUrl: text('source_url'),
    createdAt: createdAt(),
  },
  (table) => [index('product_media_product_idx').on(table.productId, table.position)],
);

export const productVariants = pgTable(
  'product_variants',
  {
    id: id(),
    productId: text('product_id')
      .notNull()
      .references(() => products.id, { onDelete: 'cascade' }),
    title: text('title').notNull(),
    sku: text('sku'),
    barcode: text('barcode'),
    priceCents: integer('price_cents').notNull(),
    compareAtCents: integer('compare_at_cents'),
    currency: currency(),
    /** `{ "Size": "L", "Colour": "Obsidian" }` */
    optionValues: jsonb('option_values').$type<Record<string, string>>().notNull().default({}),
    weightGrams: integer('weight_grams'),
    position: integer('position').notNull(),
    mediaId: text('media_id').references(() => productMedia.id, { onDelete: 'set null' }),
    legacyShopifyId: text('legacy_shopify_id'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    index('product_variants_product_idx').on(table.productId, table.position),
    uniqueIndex('product_variants_sku_key').on(table.sku),
    uniqueIndex('product_variants_legacy_key').on(table.legacyShopifyId),
    check('product_variants_price_check', sql`${table.priceCents} >= 0`),
    check(
      'product_variants_compare_check',
      sql`${table.compareAtCents} IS NULL OR ${table.compareAtCents} >= 0`,
    ),
  ],
);

export const collections = pgTable(
  'collections',
  {
    id: id(),
    handle: text('handle').notNull(),
    title: text('title').notNull(),
    description: text('description').notNull().default(''),
    published: boolean('published').notNull().default(true),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [uniqueIndex('collections_handle_key').on(table.handle)],
);

export const collectionProducts = pgTable(
  'collection_products',
  {
    collectionId: text('collection_id')
      .notNull()
      .references(() => collections.id, { onDelete: 'cascade' }),
    productId: text('product_id')
      .notNull()
      .references(() => products.id, { onDelete: 'cascade' }),
    position: integer('position').notNull().default(0),
  },
  (table) => [primaryKey({ columns: [table.collectionId, table.productId] })],
);

/* ------------------------------------------------------------------ *
 * Inventory
 * ------------------------------------------------------------------ */

/**
 * One row per variant. `available = on_hand - reserved`.
 *
 * `reserved` is stock held by open checkouts and by paid-but-unshipped orders.
 * Both counters are only ever changed by a single UPDATE with the guard in its
 * WHERE clause, so two checkouts cannot both take the last unit.
 */
export const inventoryLevels = pgTable(
  'inventory_levels',
  {
    variantId: text('variant_id')
      .primaryKey()
      .references(() => productVariants.id, { onDelete: 'cascade' }),
    onHand: integer('on_hand').notNull().default(0),
    reserved: integer('reserved').notNull().default(0),
    /** False = never limited by stock (e.g. made to order). */
    tracked: boolean('tracked').notNull().default(true),
    updatedAt: updatedAt(),
  },
  (table) => [
    check('inventory_on_hand_check', sql`${table.onHand} >= 0`),
    check('inventory_reserved_check', sql`${table.reserved} >= 0`),
  ],
);

export const inventoryReason = pgEnum('inventory_reason', [
  'initial',
  'migration',
  'correction',
  'received',
  'restock',
  'damaged',
  'shrinkage',
  'other',
  'sale',
  'cancellation',
]);

/** Append-only ledger. Every change to `on_hand` has a row here. */
export const inventoryMovements = pgTable(
  'inventory_movements',
  {
    id: id(),
    variantId: text('variant_id')
      .notNull()
      .references(() => productVariants.id, { onDelete: 'cascade' }),
    delta: integer('delta').notNull(),
    onHandAfter: integer('on_hand_after').notNull(),
    reason: inventoryReason('reason').notNull(),
    /** Order number, checkout id or free text. */
    reference: text('reference').notNull().default(''),
    actor: text('actor').notNull(),
    createdAt: createdAt(),
  },
  (table) => [index('inventory_movements_variant_idx').on(table.variantId, table.createdAt)],
);

export const reservationStatus = pgEnum('reservation_status', ['active', 'released', 'committed']);

/**
 * Stock held for one checkout. `active` rows count toward `reserved`.
 * Paying converts them to `committed` (still reserved until shipped);
 * expiry, failure or cancellation releases them.
 */
export const inventoryReservations = pgTable(
  'inventory_reservations',
  {
    id: id(),
    checkoutId: text('checkout_id').notNull(),
    variantId: text('variant_id')
      .notNull()
      .references(() => productVariants.id, { onDelete: 'cascade' }),
    quantity: integer('quantity').notNull(),
    status: reservationStatus('status').notNull().default('active'),
    expiresAt: ts('expires_at').notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    index('inventory_reservations_checkout_idx').on(table.checkoutId),
    index('inventory_reservations_expiry_idx').on(table.status, table.expiresAt),
    check('inventory_reservations_quantity_check', sql`${table.quantity} > 0`),
  ],
);

/* ------------------------------------------------------------------ *
 * Customers
 * ------------------------------------------------------------------ */

export const customers = pgTable(
  'customers',
  {
    id: id(),
    /** Stored lower-cased; uniqueness is on the stored value. */
    email: text('email').notNull(),
    /** scrypt. NULL for migrated customers who have not set a password yet. */
    passwordHash: text('password_hash'),
    firstName: text('first_name').notNull().default(''),
    lastName: text('last_name').notNull().default(''),
    phone: text('phone'),
    emailVerifiedAt: ts('email_verified_at'),
    /** Express marketing consent (CASL). Never implied by having an account. */
    marketingConsent: boolean('marketing_consent').notNull().default(false),
    marketingConsentAt: ts('marketing_consent_at'),
    marketingConsentSource: text('marketing_consent_source'),
    note: text('note').notNull().default(''),
    tags: jsonb('tags').$type<string[]>().notNull().default([]),
    disabledAt: ts('disabled_at'),
    legacyShopifyId: text('legacy_shopify_id'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    uniqueIndex('customers_email_key').on(table.email),
    uniqueIndex('customers_legacy_key').on(table.legacyShopifyId),
  ],
);

export const customerAddresses = pgTable(
  'customer_addresses',
  {
    id: id(),
    customerId: text('customer_id')
      .notNull()
      .references(() => customers.id, { onDelete: 'cascade' }),
    firstName: text('first_name').notNull().default(''),
    lastName: text('last_name').notNull().default(''),
    line1: text('line1').notNull(),
    line2: text('line2').notNull().default(''),
    city: text('city').notNull(),
    /** ISO 3166-2 subdivision code without the country, e.g. `MB`. */
    province: text('province').notNull().default(''),
    postalCode: text('postal_code').notNull(),
    /** ISO 3166-1 alpha-2. */
    country: text('country').notNull(),
    phone: text('phone'),
    isDefault: boolean('is_default').notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [index('customer_addresses_customer_idx').on(table.customerId)],
);

/**
 * Server-side sessions. The cookie holds a random token; only its SHA-256 is
 * stored, so a database leak does not yield usable sessions. Rows can be
 * revoked individually or all at once (password change).
 */
export const customerSessions = pgTable(
  'customer_sessions',
  {
    id: id(),
    customerId: text('customer_id')
      .notNull()
      .references(() => customers.id, { onDelete: 'cascade' }),
    tokenHash: text('token_hash').notNull(),
    expiresAt: ts('expires_at').notNull(),
    revokedAt: ts('revoked_at'),
    createdAt: createdAt(),
  },
  (table) => [
    uniqueIndex('customer_sessions_token_key').on(table.tokenHash),
    index('customer_sessions_customer_idx').on(table.customerId),
  ],
);

export const customerTokenKind = pgEnum('customer_token_kind', ['verify_email', 'password_reset']);

/** Single-use, expiring, hashed tokens for email verification and password reset. */
export const customerTokens = pgTable(
  'customer_tokens',
  {
    id: id(),
    customerId: text('customer_id')
      .notNull()
      .references(() => customers.id, { onDelete: 'cascade' }),
    kind: customerTokenKind('kind').notNull(),
    tokenHash: text('token_hash').notNull(),
    expiresAt: ts('expires_at').notNull(),
    usedAt: ts('used_at'),
    createdAt: createdAt(),
  },
  (table) => [uniqueIndex('customer_tokens_token_key').on(table.tokenHash)],
);

/* ------------------------------------------------------------------ *
 * Carts
 * ------------------------------------------------------------------ */

/**
 * A signed-in customer's cart, so it follows them between devices. Guests keep
 * their cart in the browser. Only identities are stored; prices are always
 * resolved from `product_variants` when the cart is read.
 */
export const carts = pgTable(
  'carts',
  {
    id: id(),
    customerId: text('customer_id')
      .notNull()
      .references(() => customers.id, { onDelete: 'cascade' }),
    updatedAt: updatedAt(),
  },
  (table) => [uniqueIndex('carts_customer_key').on(table.customerId)],
);

export const cartItems = pgTable(
  'cart_items',
  {
    cartId: text('cart_id')
      .notNull()
      .references(() => carts.id, { onDelete: 'cascade' }),
    variantId: text('variant_id')
      .notNull()
      .references(() => productVariants.id, { onDelete: 'cascade' }),
    quantity: integer('quantity').notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.cartId, table.variantId] }),
    check('cart_items_quantity_check', sql`${table.quantity} > 0`),
  ],
);

/* ------------------------------------------------------------------ *
 * Shipping, tax, discounts
 * ------------------------------------------------------------------ */

/**
 * Flat shipping rates by destination. The first active rate matching the
 * destination country (and province, when listed) is offered. There are no
 * rows until the owner enters real rates; checkout refuses to open without one.
 */
export const shippingRates = pgTable('shipping_rates', {
  id: id(),
  name: text('name').notNull(),
  /** ISO country codes; `["*"]` matches anywhere. */
  countries: jsonb('countries').$type<string[]>().notNull(),
  /** Province codes within the country; empty = whole country. */
  provinces: jsonb('provinces').$type<string[]>().notNull().default([]),
  priceCents: integer('price_cents').notNull(),
  /** Subtotal (after discounts) at or above which this rate is free. */
  freeOverCents: integer('free_over_cents'),
  /** Shown to the customer only when set. */
  deliveryEstimate: text('delivery_estimate'),
  active: boolean('active').notNull().default(true),
  position: integer('position').notNull().default(0),
  currency: currency(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

/**
 * Sales tax by destination. Several rows may apply to one address (GST + PST);
 * each becomes its own tax line on the order. Empty until the owner confirms
 * the business's tax registrations — an unregistered seller charges no tax.
 */
export const taxRates = pgTable(
  'tax_rates',
  {
    id: id(),
    country: text('country').notNull(),
    /** Empty = applies to the whole country. */
    province: text('province').notNull().default(''),
    name: text('name').notNull(),
    rateBps: integer('rate_bps').notNull(),
    appliesToShipping: boolean('applies_to_shipping').notNull().default(true),
    active: boolean('active').notNull().default(true),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    index('tax_rates_region_idx').on(table.country, table.province),
    check('tax_rates_rate_check', sql`${table.rateBps} >= 0 AND ${table.rateBps} <= 5000`),
  ],
);

export const discountStatus = pgEnum('discount_status', ['active', 'paused', 'ended']);

/**
 * An enforceable discount. Created when an Owner activates an offer draft
 * (src/domain/offers.ts); the definition is copied here so a later edit to the
 * draft can never silently change what checkout charges.
 */
export const discounts = pgTable(
  'discounts',
  {
    id: id(),
    offerId: text('offer_id'),
    title: text('title').notNull(),
    kind: text('kind').notNull(),
    method: text('method').notNull(),
    /** Upper-cased. NULL for automatic discounts. */
    code: text('code'),
    percentOff: integer('percent_off').notNull(),
    minQuantity: integer('min_quantity'),
    audience: text('audience').notNull().default('everyone'),
    eligibility: jsonb('eligibility')
      .$type<{ scope: string; productSlugs: string[]; categories: string[]; excludeSaleItems: boolean }>()
      .notNull(),
    startsAt: ts('starts_at'),
    endsAt: ts('ends_at'),
    usageLimit: integer('usage_limit'),
    usedCount: integer('used_count').notNull().default(0),
    oncePerCustomer: boolean('once_per_customer').notNull().default(false),
    status: discountStatus('status').notNull().default('active'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    uniqueIndex('discounts_code_key').on(table.code),
    check('discounts_percent_check', sql`${table.percentOff} BETWEEN 1 AND 100`),
  ],
);

/* ------------------------------------------------------------------ *
 * Checkout
 * ------------------------------------------------------------------ */

export const checkoutStatus = pgEnum('checkout_status', ['open', 'completed', 'expired', 'cancelled']);

export interface CheckoutLineSnapshot {
  variantId: string;
  productId: string;
  productHandle: string;
  /** Taxonomy group at the time of checkout, for category-scoped discounts. */
  categoryGroup: string | null;
  title: string;
  variantTitle: string;
  sku: string | null;
  quantity: number;
  unitPriceCents: number;
  compareAtCents: number | null;
  /** Discount allocated to this line, in cents. */
  discountCents: number;
  imageUrl: string | null;
}

export interface AddressSnapshot {
  firstName: string;
  lastName: string;
  line1: string;
  line2: string;
  city: string;
  province: string;
  postalCode: string;
  country: string;
  phone: string | null;
}

export interface TaxLineSnapshot {
  name: string;
  rateBps: number;
  amountCents: number;
}

/**
 * A priced, stock-reserved attempt to buy. Totals are computed on the server
 * and frozen here; the payment intent is created for exactly `total_cents`.
 * It also drives abandoned-checkout recovery, which is only ever sent when
 * `recovery_consent` is true.
 */
export const checkouts = pgTable(
  'checkouts',
  {
    id: id(),
    /** SHA-256 of the bearer token held in the customer's cookie. */
    tokenHash: text('token_hash').notNull(),
    status: checkoutStatus('status').notNull().default('open'),
    customerId: text('customer_id').references(() => customers.id, { onDelete: 'set null' }),
    email: text('email'),
    recoveryConsent: boolean('recovery_consent').notNull().default(false),
    recoverySentAt: ts('recovery_sent_at'),
    lines: jsonb('lines').$type<CheckoutLineSnapshot[]>().notNull(),
    shippingAddress: jsonb('shipping_address').$type<AddressSnapshot>(),
    shippingRateId: text('shipping_rate_id'),
    shippingName: text('shipping_name'),
    discountId: text('discount_id'),
    discountCode: text('discount_code'),
    discountTitle: text('discount_title'),
    taxLines: jsonb('tax_lines').$type<TaxLineSnapshot[]>().notNull().default([]),
    subtotalCents: integer('subtotal_cents').notNull(),
    discountCents: integer('discount_cents').notNull().default(0),
    shippingCents: integer('shipping_cents').notNull().default(0),
    taxCents: integer('tax_cents').notNull().default(0),
    totalCents: integer('total_cents').notNull(),
    currency: currency(),
    paymentProvider: text('payment_provider'),
    /** Provider's payment reference (Stripe PaymentIntent id). */
    paymentRef: text('payment_ref'),
    expiresAt: ts('expires_at').notNull(),
    completedAt: ts('completed_at'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    uniqueIndex('checkouts_token_key').on(table.tokenHash),
    uniqueIndex('checkouts_payment_ref_key').on(table.paymentRef),
    index('checkouts_status_idx').on(table.status, table.expiresAt),
  ],
);

/* ------------------------------------------------------------------ *
 * Orders
 * ------------------------------------------------------------------ */

export const orderPaymentStatus = pgEnum('order_payment_status', [
  'pending_payment',
  'paid',
  'partially_refunded',
  'refunded',
]);

export const orderFulfillmentStatus = pgEnum('order_fulfillment_status', [
  'unfulfilled',
  'partially_fulfilled',
  'fulfilled',
]);

export const orderSource = pgEnum('order_source', ['native', 'shopify_import']);

/**
 * A durable order. Created in exactly one place: when a payment provider
 * confirms, by signed webhook, that a checkout was paid. `checkout_id` and
 * `payment_ref` are unique, which is what makes a replayed webhook a no-op.
 */
export const orders = pgTable(
  'orders',
  {
    id: id(),
    /** Human order number. `#1001` style, allocated by the sequence. */
    number: serial('number').notNull(),
    /** Display name. Native: `#<number>`. Imported: the legacy name. */
    name: text('name').notNull(),
    source: orderSource('source').notNull().default('native'),
    customerId: text('customer_id').references(() => customers.id, { onDelete: 'set null' }),
    email: text('email').notNull(),
    paymentStatus: orderPaymentStatus('payment_status').notNull(),
    fulfillmentStatus: orderFulfillmentStatus('fulfillment_status').notNull().default('unfulfilled'),
    cancelledAt: ts('cancelled_at'),
    cancelReason: text('cancel_reason'),
    currency: currency(),
    subtotalCents: integer('subtotal_cents').notNull(),
    discountCents: integer('discount_cents').notNull().default(0),
    shippingCents: integer('shipping_cents').notNull().default(0),
    taxCents: integer('tax_cents').notNull().default(0),
    totalCents: integer('total_cents').notNull(),
    refundedCents: integer('refunded_cents').notNull().default(0),
    taxLines: jsonb('tax_lines').$type<TaxLineSnapshot[]>().notNull().default([]),
    discountId: text('discount_id'),
    discountCode: text('discount_code'),
    shippingAddress: jsonb('shipping_address').$type<AddressSnapshot>(),
    shippingName: text('shipping_name'),
    note: text('note').notNull().default(''),
    checkoutId: text('checkout_id'),
    paymentProvider: text('payment_provider'),
    paymentRef: text('payment_ref'),
    /** True for orders paid through a provider's test mode. Excluded from reports. */
    test: boolean('test').notNull().default(false),
    legacyShopifyId: text('legacy_shopify_id'),
    placedAt: ts('placed_at').notNull().defaultNow(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    uniqueIndex('orders_number_key').on(table.number),
    uniqueIndex('orders_checkout_key').on(table.checkoutId),
    uniqueIndex('orders_payment_ref_key').on(table.paymentRef),
    uniqueIndex('orders_legacy_key').on(table.legacyShopifyId),
    index('orders_customer_idx').on(table.customerId, table.placedAt),
    index('orders_email_idx').on(table.email),
    index('orders_placed_idx').on(table.placedAt),
    check('orders_refunded_check', sql`${table.refundedCents} >= 0 AND ${table.refundedCents} <= ${table.totalCents}`),
  ],
);

export const orderItems = pgTable(
  'order_items',
  {
    id: id(),
    orderId: text('order_id')
      .notNull()
      .references(() => orders.id, { onDelete: 'cascade' }),
    /** Nullable: the order outlives the product it was for. */
    variantId: text('variant_id').references(() => productVariants.id, { onDelete: 'set null' }),
    productId: text('product_id').references(() => products.id, { onDelete: 'set null' }),
    /** Snapshots, so a later rename or price change never rewrites history. */
    title: text('title').notNull(),
    variantTitle: text('variant_title').notNull().default(''),
    sku: text('sku'),
    imageUrl: text('image_url'),
    quantity: integer('quantity').notNull(),
    unitPriceCents: integer('unit_price_cents').notNull(),
    discountCents: integer('discount_cents').notNull().default(0),
    /** quantity × unit price − discount. */
    totalCents: integer('total_cents').notNull(),
    fulfilledQuantity: integer('fulfilled_quantity').notNull().default(0),
    refundedQuantity: integer('refunded_quantity').notNull().default(0),
  },
  (table) => [
    index('order_items_order_idx').on(table.orderId),
    check('order_items_quantity_check', sql`${table.quantity} > 0`),
    check(
      'order_items_fulfilled_check',
      sql`${table.fulfilledQuantity} >= 0 AND ${table.fulfilledQuantity} <= ${table.quantity}`,
    ),
  ],
);

/** Money movements against an order: the charge, and each refund. */
export const payments = pgTable(
  'payments',
  {
    id: id(),
    orderId: text('order_id')
      .notNull()
      .references(() => orders.id, { onDelete: 'cascade' }),
    kind: text('kind').notNull(),
    provider: text('provider').notNull(),
    /** Provider's id for this movement. Unique: the idempotency key for refunds. */
    providerRef: text('provider_ref').notNull(),
    amountCents: integer('amount_cents').notNull(),
    currency: currency(),
    status: text('status').notNull(),
    reason: text('reason').notNull().default(''),
    actor: text('actor').notNull().default('system'),
    createdAt: createdAt(),
  },
  (table) => [
    uniqueIndex('payments_provider_ref_key').on(table.provider, table.providerRef),
    index('payments_order_idx').on(table.orderId),
  ],
);

export const fulfillments = pgTable(
  'fulfillments',
  {
    id: id(),
    orderId: text('order_id')
      .notNull()
      .references(() => orders.id, { onDelete: 'cascade' }),
    trackingCompany: text('tracking_company'),
    trackingNumber: text('tracking_number'),
    trackingUrl: text('tracking_url'),
    /** `{ orderItemId: quantity }` */
    items: jsonb('items').$type<Record<string, number>>().notNull(),
    shippedAt: ts('shipped_at').notNull().defaultNow(),
    /** Set only on evidence (carrier or staff confirmation). Never assumed. */
    deliveredAt: ts('delivered_at'),
    actor: text('actor').notNull(),
    createdAt: createdAt(),
  },
  (table) => [index('fulfillments_order_idx').on(table.orderId)],
);

/** Order timeline: what happened, when, and who or what did it. */
export const orderEvents = pgTable(
  'order_events',
  {
    id: id(),
    orderId: text('order_id')
      .notNull()
      .references(() => orders.id, { onDelete: 'cascade' }),
    type: text('type').notNull(),
    message: text('message').notNull(),
    actor: text('actor').notNull().default('system'),
    createdAt: createdAt(),
  },
  (table) => [index('order_events_order_idx').on(table.orderId, table.createdAt)],
);

/** One row per order a discount was used on. Enforces once-per-customer. */
export const discountRedemptions = pgTable(
  'discount_redemptions',
  {
    discountId: text('discount_id')
      .notNull()
      .references(() => discounts.id, { onDelete: 'cascade' }),
    orderId: text('order_id')
      .notNull()
      .references(() => orders.id, { onDelete: 'cascade' }),
    email: text('email').notNull(),
    createdAt: createdAt(),
  },
  (table) => [
    primaryKey({ columns: [table.discountId, table.orderId] }),
    index('discount_redemptions_email_idx').on(table.discountId, table.email),
  ],
);

/* ------------------------------------------------------------------ *
 * Infrastructure
 * ------------------------------------------------------------------ */

/**
 * Provider webhook receipts. The primary key is the provider's event id, so
 * inserting it is the idempotency check: a replay conflicts and is skipped.
 */
export const webhookEvents = pgTable('webhook_events', {
  id: text('id').primaryKey(),
  provider: text('provider').notNull(),
  type: text('type').notNull(),
  status: text('status').notNull().default('processing'),
  receivedAt: timestamp('received_at', { withTimezone: true }).notNull().defaultNow(),
  processedAt: ts('processed_at'),
});

/**
 * Document store for non-relational records (site content, offer drafts,
 * drops, consent records, tickets, staff, audit log). Same interface as the
 * file and KV adapters, so the whole platform needs one database.
 */
export const documents = pgTable(
  'documents',
  {
    collection: text('collection').notNull(),
    id: text('id').notNull(),
    data: jsonb('data').notNull(),
    updatedAt: updatedAt(),
  },
  (table) => [primaryKey({ columns: [table.collection, table.id] })],
);
